#!/usr/bin/env python3
"""Generate calls to every public facade from a vendored synthetic wire corpus."""
import json,pathlib,sys
R=pathlib.Path(__file__).resolve().parents[1]
def upper(s):return s[:1].upper()+s[1:]
lines=['// Generated by scripts/generate_tests.py.','import Foundation','import XCTest','@testable import Webmania','final class OperationTests: XCTestCase, @unchecked Sendable {','    func testAllOperationFacadesOverHTTP() async throws {','        let fixtures = try JSONValue.parse(Data(contentsOf:Bundle.module.url(forResource:"operations",withExtension:"json",subdirectory:"Fixtures")!))["cases"]!.array!','        var count = 0','        for fixture in fixtures {','            let id = fixture["operation"]!.string!','            var raw = fixture["path_params"]!.object!','            for (k,v) in fixture["query"]!.object! { raw[k] = v }','            if fixture["has_request"] == .bool(true) { raw["body"] = fixture["request"]! }','            let client = try TestSupport.client("contract/"+id,credentials:TestSupport.credentials(for:id))','            switch id {']
ops=json.loads((R/'Sources/Webmania/Resources/contracts/operations.json').read_text())
for op in ops:
 name=upper(op['id'])+'Parameters'
 if not op['enabled']:
  lines+=['            case '+json.dumps(op['id'])+': do { _ = try await client.'+op['id']+'(try '+name+'(json:.object(raw))); XCTFail("Gated operation dispatched") } catch let e as SDKError { XCTAssertEqual(e.kind,.gated) }']
 else:lines+=['            case '+json.dumps(op['id'])+': _ = try await client.'+op['id']+'(try '+name+'(json:.object(raw))); count += 1']
lines+=['            default: XCTFail("Unknown fixture")','            }','        }','        XCTAssertEqual(count,'+str(sum(1 for op in ops if op['enabled']))+')','    }','}']
out='\n'.join(lines)+'\n'
path=R/'Tests/WebmaniaTests/OperationTests.swift'
if '--check' in sys.argv:
 if path.read_text()!=out:raise SystemExit('Generated operation tests differ')
else:path.write_text(out)
